package com.jonathang;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(TickFixerConfig.GROUP_NAME)
public interface TickFixerConfig extends Config
{
	String GROUP_NAME = "tickFixerForMac";

	@ConfigSection(
		name = "Keepalive Settings",
		description = "Configure the Wi-Fi keepalive mechanism",
		position = 0
	)
	String keepaliveSection = "keepalive";

	@ConfigSection(
		name = "Diagnostics",
		description = "Tick quality monitoring",
		position = 1
	)
	String diagnosticsSection = "diagnostics";

	@ConfigItem(
		keyName = "keepaliveIntervalMs",
		name = "Keepalive Interval (ms)",
		description = "How often to send a keepalive UDP packet. Lower values keep the Wi-Fi radio more active but use slightly more power. 50ms is recommended.",
		position = 0,
		section = keepaliveSection
	)
	@Range(min = 10, max = 200)
	default int keepaliveIntervalMs()
	{
		return 50;
	}

	@ConfigItem(
		keyName = "targetHost",
		name = "Target Host",
		description = "The host to send keepalive packets to. Default uses your default gateway. Use 'gateway' for auto-detection, or specify an IP address.",
		position = 1,
		section = keepaliveSection
	)
	default String targetHost()
	{
		return "gateway";
	}

	@ConfigItem(
		keyName = "targetPort",
		name = "Target Port",
		description = "UDP port to send keepalive packets to. Port 9 is the discard service (RFC 863) and won't generate ICMP responses on most routers.",
		position = 2,
		section = keepaliveSection
	)
	@Range(min = 1, max = 65535)
	default int targetPort()
	{
		return 9;
	}

	@ConfigItem(
		keyName = "onlyWhenLoggedIn",
		name = "Only When Logged In",
		description = "Only send keepalive packets when logged into a game world.",
		position = 3,
		section = keepaliveSection
	)
	default boolean onlyWhenLoggedIn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Tick Quality Overlay",
		description = "Display a small overlay showing tick quality percentage and keepalive status.",
		position = 0,
		section = diagnosticsSection
	)
	default boolean showOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "tickSampleSize",
		name = "Tick Sample Size",
		description = "Number of recent ticks to use when calculating tick quality.",
		position = 1,
		section = diagnosticsSection
	)
	@Range(min = 10, max = 500)
	default int tickSampleSize()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "tickQualityThresholdMs",
		name = "Quality Threshold (ms)",
		description = "Maximum deviation from 600ms for a tick to be considered 'good'. A tick arriving between 600-threshold and 600+threshold is counted as good quality.",
		position = 2,
		section = diagnosticsSection
	)
	@Range(min = 5, max = 100)
	default int tickQualityThresholdMs()
	{
		return 30;
	}
}

package com.jonathang;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class TickFixerOverlay extends OverlayPanel
{
	private final TickFixerPlugin plugin;
	private final TickFixerConfig config;

	@Inject
	public TickFixerOverlay(TickFixerPlugin plugin, TickFixerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		TickQualityTracker tracker = plugin.getTickQualityTracker();
		if (tracker == null)
		{
			return null;
		}

		double quality = tracker.getTickQuality();
		double avgTick = tracker.getAverageTickMs();
		double jitter = tracker.getJitterMs();
		long lastDelta = tracker.getLastTickDeltaMs();

		// Color code the quality percentage
		Color qualityColor;
		if (quality >= 95)
		{
			qualityColor = Color.GREEN;
		}
		else if (quality >= 80)
		{
			qualityColor = Color.YELLOW;
		}
		else if (quality >= 60)
		{
			qualityColor = Color.ORANGE;
		}
		else
		{
			qualityColor = Color.RED;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Tick Fixer")
			.color(Color.WHITE)
			.build());

		if (tracker.isWaiting())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Status")
				.right("Waiting...")
				.rightColor(Color.YELLOW)
				.build());
		}
		else
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Tick Quality")
				.right(String.format("%.1f%%", quality))
				.rightColor(qualityColor)
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Avg Tick")
				.right(String.format("%.0fms", avgTick))
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Jitter")
				.right(String.format("%.1fms", jitter))
				.rightColor(jitter > 30 ? Color.ORANGE : Color.WHITE)
				.build());

			if (lastDelta >= 0)
			{
				Color deltaColor = Math.abs(lastDelta - 600) <= config.tickQualityThresholdMs()
					? Color.GREEN : Color.RED;
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Last Tick")
					.right(lastDelta + "ms")
					.rightColor(deltaColor)
					.build());
			}
		}

		addKeepaliveStatus();

		return super.render(graphics);
	}

	private void addKeepaliveStatus()
	{
		WifiKeepaliveThread keepalive = plugin.getKeepaliveThread();
		String keepaliveStatus;
		Color keepaliveColor;
		if (keepalive == null || !keepalive.isRunning())
		{
			keepaliveStatus = "OFF";
			keepaliveColor = Color.GRAY;
		}
		else if (keepalive.isPaused())
		{
			keepaliveStatus = "PAUSED";
			keepaliveColor = Color.YELLOW;
		}
		else
		{
			keepaliveStatus = "ACTIVE";
			keepaliveColor = Color.GREEN;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Keepalive")
			.right(keepaliveStatus)
			.rightColor(keepaliveColor)
			.build());
	}
}

package com.jonathang;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.ChatMessageType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Tick Fixer for Mac",
	description = "Prevents macOS Wi-Fi power save from degrading tick quality by sending keepalive packets. "
		+ "Useful for tick manipulation activities like 2t woodcutting, 3t fishing, and prayer flicking.",
	tags = {"tick", "wifi", "macos", "latency", "jitter", "keepalive", "tick manipulation", "flicker", "flick"}
)
public class TickFixerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private TickFixerConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TickFixerOverlay overlay;

	@Getter
	private TickQualityTracker tickQualityTracker;

	@Getter
	private WifiKeepaliveThread keepaliveThread;

	@Provides
	TickFixerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TickFixerConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateConfig();

		boolean isMacOS = System.getProperty("os.name", "").toLowerCase().contains("mac");

		if (!isMacOS)
		{
			log.info("Tick Fixer: Not running on macOS — keepalive thread disabled. "
				+ "Tick quality overlay is still active.");
		}

		tickQualityTracker = new TickQualityTracker(
			config.tickSampleSize(),
			config.tickQualityThresholdMs()
		);

		overlayManager.add(overlay);

		if (isMacOS)
		{
			startKeepalive();
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		stopKeepalive();
		tickQualityTracker = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (tickQualityTracker != null)
		{
			tickQualityTracker.recordTick();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && tickQualityTracker != null)
		{
			tickQualityTracker.reset();
		}

		if (keepaliveThread == null)
		{
			return;
		}

		if (config.onlyWhenLoggedIn())
		{
			if (event.getGameState() == GameState.LOGGED_IN)
			{
				keepaliveThread.unpause();
				log.debug("Keepalive resumed — logged in");
			}
			else if (event.getGameState() == GameState.LOGIN_SCREEN
				|| event.getGameState() == GameState.CONNECTION_LOST)
			{
				keepaliveThread.pause();
				log.debug("Keepalive paused — not logged in (state={})", event.getGameState());
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TickFixerConfig.GROUP_NAME.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "keepaliveIntervalMs":
				if (keepaliveThread != null)
				{
					keepaliveThread.setInterval(config.keepaliveIntervalMs());
					log.debug("Keepalive interval updated to {}ms", config.keepaliveIntervalMs());
				}
				break;

			case "targetHost":
			case "targetPort":
				if (keepaliveThread != null)
				{
					String host = config.targetHost();
					keepaliveThread.resolveAndSetTarget(host, config.targetPort(),
						() -> log.debug("Keepalive target updated"),
						() ->
						{
							keepaliveThread.pause();
							clientThread.invokeLater(() ->
								client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
									"Tick Fixer: Failed to resolve host '" + host + "'. Keepalive is paused until a valid host is set.",
									null));
						});
				}
				break;

			case "tickQualityThresholdMs":
				if (tickQualityTracker != null)
				{
					tickQualityTracker.setThresholdMs(config.tickQualityThresholdMs());
				}
				break;

			case "tickSampleSize":
				// Recreate the tracker with the new sample size
				if (tickQualityTracker != null)
				{
					tickQualityTracker = new TickQualityTracker(
						config.tickSampleSize(),
						config.tickQualityThresholdMs()
					);
				}
				break;
		}
	}

	private void migrateConfig()
	{
		String oldIpAddress = configManager.getConfiguration(TickFixerConfig.GROUP_NAME, "ipAddress");
		if (oldIpAddress != null)
		{
			log.info("Migrating config key 'ipAddress' -> 'targetHost' (value={})", oldIpAddress);
			configManager.setConfiguration(TickFixerConfig.GROUP_NAME, "targetHost", oldIpAddress);
			configManager.unsetConfiguration(TickFixerConfig.GROUP_NAME, "ipAddress");
		}

		// Clean up old v1 pingInterval key — not migrated since the new default (50ms) is preferred
		configManager.unsetConfiguration(TickFixerConfig.GROUP_NAME, "pingInterval");
	}

	private void startKeepalive()
	{
		if (keepaliveThread != null && keepaliveThread.isRunning())
		{
			return;
		}

		keepaliveThread = new WifiKeepaliveThread();
		keepaliveThread.setInterval(config.keepaliveIntervalMs());

		// If configured to only run when logged in, start paused
		if (config.onlyWhenLoggedIn() && client.getGameState() != GameState.LOGGED_IN)
		{
			keepaliveThread.pause();
		}

		keepaliveThread.start();

		// Resolve target asynchronously on the keepalive executor thread
		keepaliveThread.resolveAndSetTarget(config.targetHost(), config.targetPort(),
			null,
			() -> log.error("Failed to resolve keepalive target, keepalive will not send packets"));

		log.info("Wi-Fi keepalive started, resolving target asynchronously (interval={}ms)", config.keepaliveIntervalMs());
	}

	private void stopKeepalive()
	{
		if (keepaliveThread != null)
		{
			keepaliveThread.shutdown();
			keepaliveThread = null;
		}
	}
}

package com.jonathang;

import lombok.Setter;

/**
 * Measures tick quality by tracking the interval between consecutive GameTick events.
 * Uses a ring buffer of recent tick deltas and calculates the percentage that fall
 * within an acceptable threshold of the ideal 600ms.
 */
public class TickQualityTracker
{
	private static final long IDEAL_TICK_MS = 600;
	private static final int DISREGARD_TICKS = 15;

	private final long[] tickDeltas;
	private final int capacity;
	private int head = 0;
	private int count = 0;
	private long lastTickNanos = 0;
	@Setter
	private int thresholdMs;
	private int disregardRemaining = DISREGARD_TICKS;

	public TickQualityTracker(int sampleSize, int thresholdMs)
	{
		this.capacity = sampleSize;
		this.tickDeltas = new long[sampleSize];
		this.thresholdMs = thresholdMs;
	}

	/**
	 * Call this on every GameTick event.
	 *
	 * <p>The first DISREGARD_TICKS ticks after a reset are skipped to allow
	 * the game to stabilize after login or world hop.
	 */
	public void recordTick()
	{
		long now = System.nanoTime();
		if (disregardRemaining > 0)
		{
			disregardRemaining--;
			lastTickNanos = now;
			return;
		}
		if (lastTickNanos != 0)
		{
			long deltaMs = (now - lastTickNanos) / 1_000_000L;
			tickDeltas[head] = deltaMs;
			head = (head + 1) % capacity;
			if (count < capacity)
			{
				count++;
			}
		}
		lastTickNanos = now;
	}

	/**
	 * Returns true if the tracker is still in the disregard period after a reset.
	 */
	public boolean isWaiting()
	{
		return disregardRemaining > 0;
	}

	/**
	 * Returns tick quality as a percentage (0-100).
	 *
	 * <p>A tick is "good" if its delta is within thresholdMs of IDEAL_TICK_MS.
	 */
	public double getTickQuality()
	{
		if (count == 0)
		{
			return 100.0;
		}

		int goodTicks = 0;
		for (int i = 0; i < count; i++)
		{
			long delta = tickDeltas[i];
			if (Math.abs(delta - IDEAL_TICK_MS) <= thresholdMs)
			{
				goodTicks++;
			}
		}

		return (goodTicks * 100.0) / count;
	}

	/**
	 * Returns the average tick delta in ms over the sample window.
	 */
	public double getAverageTickMs()
	{
		if (count == 0)
		{
			return IDEAL_TICK_MS;
		}

		long sum = 0;
		for (int i = 0; i < count; i++)
		{
			sum += tickDeltas[i];
		}
		return (double) sum / count;
	}

	/**
	 * Returns the standard deviation of tick deltas (jitter) in ms.
	 */
	public double getJitterMs()
	{
		if (count < 2)
		{
			return 0.0;
		}

		double mean = getAverageTickMs();
		double sumSqDiff = 0;
		for (int i = 0; i < count; i++)
		{
			double diff = tickDeltas[i] - mean;
			sumSqDiff += diff * diff;
		}
		return Math.sqrt(sumSqDiff / count);
	}

	/**
	 * Returns the most recent tick delta in ms, or -1 if no data.
	 */
	public long getLastTickDeltaMs()
	{
		if (count == 0)
		{
			return -1;
		}
		int lastIdx = (head - 1 + capacity) % capacity;
		return tickDeltas[lastIdx];
	}

	/**
	 * Reset all collected data and restart the disregard period.
	 */
	public void reset()
	{
		head = 0;
		count = 0;
		lastTickNanos = 0;
		disregardRemaining = DISREGARD_TICKS;
	}

}

package com.jonathang;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends small UDP keepalive packets at a configurable interval to prevent the
 * macOS Wi-Fi radio from entering 802.11 power save mode.
 *
 * <p>When the Wi-Fi radio enters power save, the access point buffers packets destined
 * for the client until the radio wakes and polls. This introduces jitter in packet
 * delivery timing, which degrades tick quality in OSRS since the server sends update
 * packets on a strict 600ms cadence.
 *
 * <p>By maintaining a steady stream of small outbound UDP packets, we signal to the
 * Wi-Fi firmware that the connection is active, preventing it from entering the
 * power save polling state.
 */
@Slf4j
public class WifiKeepaliveThread
{
	/** Single-byte payload — minimal packet to keep the radio awake */
	private static final byte[] KEEPALIVE_PAYLOAD = new byte[]{0x00};

	private final AtomicBoolean running = new AtomicBoolean(false);
	private final AtomicBoolean paused = new AtomicBoolean(false);
	private final AtomicInteger intervalMs = new AtomicInteger(50);
	private final AtomicReference<InetAddress> targetAddress = new AtomicReference<>();
	private final AtomicInteger targetPort = new AtomicInteger(9);

	private ScheduledExecutorService executor;
	private ScheduledFuture<?> scheduledTask;
	private DatagramSocket socket;
	private long totalPacketsSent = 0;
	private long totalErrors = 0;

	/**
	 * Attempt to detect the default gateway IP by parsing the output of `route` or `netstat`.
	 * Falls back to the router's common default if detection fails.
	 */
	public static InetAddress detectDefaultGateway()
	{
		try
		{
			// macOS: `route -n get default` prints the gateway
			Process process = Runtime.getRuntime().exec(new String[]{"route", "-n", "get", "default"});
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream())))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					line = line.trim();
					if (line.startsWith("gateway:"))
					{
						String gateway = line.substring("gateway:".length()).trim();
						log.info("Detected default gateway: {}", gateway);
						return InetAddress.getByName(gateway);
					}
				}
			}
			if (!process.waitFor(500, TimeUnit.MILLISECONDS))
			{
				process.destroyForcibly();
				log.warn("route command timed out after 500ms");
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to detect default gateway via route command", e);
		}

		// Fallback: try common gateway addresses
		try
		{
			InetAddress candidate = InetAddress.getByName("192.168.1.1");
			if (candidate.isReachable(500))
			{
				log.info("Using fallback gateway: {}", candidate.getHostAddress());
				return candidate;
			}
		}
		catch (Exception e)
		{
			// ignore
		}

		try
		{
			// Last resort: use Google DNS. Packets leave the local network, but it's reliable.
			log.info("Using fallback target: 8.8.8.8");
			return InetAddress.getByName("8.8.8.8");
		}
		catch (Exception e)
		{
			log.error("Failed to resolve any keepalive target", e);
			return null;
		}
	}

	/**
	 * Resolve the target address from the config string.
	 *
	 * <p>"gateway" triggers auto-detection; anything else is treated as a hostname/IP.
	 */
	public static InetAddress resolveTarget(String configValue)
	{
		if (configValue == null || configValue.trim().isEmpty() || configValue.trim().equalsIgnoreCase("gateway"))
		{
			return detectDefaultGateway();
		}

		try
		{
			return InetAddress.getByName(configValue.trim());
		}
		catch (Exception e)
		{
			log.error("Failed to resolve target host '{}', falling back to gateway detection", configValue, e);
			return detectDefaultGateway();
		}
	}

	public void configure(InetAddress target, int port, int interval)
	{
		this.targetAddress.set(target);
		this.targetPort.set(port);
		this.intervalMs.set(interval);
	}

	public void setInterval(int ms)
	{
		this.intervalMs.set(Math.max(10, Math.min(200, ms)));
		reschedule();
	}

	public void setTarget(InetAddress address, int port)
	{
		this.targetAddress.set(address);
		this.targetPort.set(port);
	}

	/**
	 * Resolve the target address asynchronously on this thread's executor,
	 * so no blocking occurs on RuneLite's client threads.
	 */
	public void resolveAndSetTarget(String configValue, int port, Runnable onSuccess, Runnable onFailure)
	{
		if (executor == null || !running.get())
		{
			return;
		}

		executor.submit(() ->
		{
			InetAddress resolved = resolveTarget(configValue);
			if (resolved != null)
			{
				targetAddress.set(resolved);
				targetPort.set(port);
				log.info("Resolved keepalive target: {}:{}", resolved.getHostAddress(), port);
				if (onSuccess != null)
				{
					onSuccess.run();
				}
			}
			else
			{
				log.error("Failed to resolve keepalive target '{}'", configValue);
				if (onFailure != null)
				{
					onFailure.run();
				}
			}
		});
	}

	public void pause()
	{
		paused.set(true);
	}

	public void unpause()
	{
		paused.set(false);
	}

	public boolean isPaused()
	{
		return paused.get();
	}

	public boolean isRunning()
	{
		return running.get();
	}

	public void start()
	{
		if (running.get())
		{
			return;
		}

		try
		{
			socket = new DatagramSocket();
			socket.setSoTimeout(100);
		}
		catch (Exception e)
		{
			log.error("Failed to create keepalive socket", e);
			return;
		}

		executor = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "wifi-keepalive");
			t.setDaemon(true);
			return t;
		});

		running.set(true);
		schedule();

		log.info("Wi-Fi keepalive started (interval={}ms, target={}:{})",
			intervalMs.get(),
			targetAddress.get() != null ? targetAddress.get().getHostAddress() : "null",
			targetPort.get());
	}

	public void shutdown()
	{
		if (!running.compareAndSet(true, false))
		{
			return;
		}

		if (scheduledTask != null)
		{
			scheduledTask.cancel(false);
			scheduledTask = null;
		}

		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}

		if (socket != null)
		{
			socket.close();
			socket = null;
		}

		log.info("Wi-Fi keepalive stopped (sent {} packets, {} errors)", totalPacketsSent, totalErrors);
	}

	private void schedule()
	{
		scheduledTask = executor.scheduleAtFixedRate(
			this::sendKeepalive,
			0,
			intervalMs.get(),
			TimeUnit.MILLISECONDS
		);
	}

	private void reschedule()
	{
		if (!running.get() || executor == null)
		{
			return;
		}

		if (scheduledTask != null)
		{
			scheduledTask.cancel(false);
		}

		schedule();
	}

	private void sendKeepalive()
	{
		if (paused.get())
		{
			return;
		}

		InetAddress target = targetAddress.get();
		if (target == null)
		{
			return;
		}

		try
		{
			DatagramPacket packet = new DatagramPacket(
				KEEPALIVE_PAYLOAD,
				KEEPALIVE_PAYLOAD.length,
				target,
				targetPort.get()
			);
			socket.send(packet);
			totalPacketsSent++;
		}
		catch (Exception e)
		{
			totalErrors++;
			if (totalErrors % 100 == 1)
			{
				log.debug("Keepalive send error (total errors: {}): {}", totalErrors, e.getMessage());
			}
		}
	}
}

